from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if (r,c) in seen or grid[r][c]==9: continue
  col=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
  while q:
   a,b=q.pop(); cells.append((a,b))
   for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
    if 0<=x<R and 0<=y<C and (x,y) not in seen and grid[x][y]==col:
     seen.add((x,y)); q.append((x,y))
  comps.append((col,len(cells),min(a for a,b in cells),max(a for a,b in cells),min(b for a,b in cells),max(b for a,b in cells),cells))
[(x[:6]) for x in comps]

for i,l in enumerate(lines):
 d=json.loads(l); m=d.get('message',{});
 if m.get('role')=='assistant': print(i,str(m.get('content'))[:150])

actions=[]
for i,l in enumerate(lines):
 d=json.loads(l); m=d.get('message',{})
 if m.get('role')=='assistant':
  for part in m.get('content',[]):
   if part.get('type')=='text' and part.get('text','').startswith('{"action"'):
    try: actions.append((i,json.loads(part['text'])))
    except: pass
[(i,a['action'],len(a.get('grid',[]))) for i,a in actions]

pred=[[9]*C for _ in range(R)]
for col,n,r0,r1,c0,c1,cells in comps:
 if n>=2:
  for r in range(r0,r1+1):
   for c in range(c0,c1+1): pred[r][c]=col
# But background 9 preserved, not set? all 9 default.
[(r,c,pred[r][c],out[r][c]) for r in range(R) for c in range(C) if pred[r][c]!=out[r][c]]

